 37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
 38	import org.springframework.samples.petclinic.rest.dto.PetDto;
 39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
 40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
 41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
 42	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
 43	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
 44	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
 45	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
 46	import org.springframework.samples.petclinic.rest.validation.MissingRequiredFieldsException;
 47	import org.springframework.samples.petclinic.rest.validation.OwnerEmail;
 48	import org.springframework.samples.petclinic.rest.validation.OwnerPostcode;
 49	import org.springframework.samples.petclinic.rest.validation.OwnerRegistrationDate;
 50	import org.springframework.samples.petclinic.rest.validation.OwnerTelephone;
 51	import org.springframework.samples.petclinic.rest.validation.RequiredOwnerFields;
 52	import org.springframework.samples.petclinic.service.ClinicService;
 53	import org.springframework.samples.petclinic.util.AddressNormalizer;
 54	import org.springframework.samples.petclinic.util.BusinessDays;
 55	import org.springframework.security.access.prepost.PreAuthorize;
 56	import org.springframework.web.bind.annotation.CrossOrigin;
 57	import org.springframework.web.bind.annotation.RequestMapping;
 58	import org.springframework.web.bind.annotation.RestController;
 59	import org.springframework.web.util.UriComponentsBuilder;
 60	
 61	import jakarta.transaction.Transactional;
 62	
 63	/**
 64	 * @author Vitaliy Fedoriv
 65	 */
 66	
 67	@RestController
 68	@CrossOrigin(exposedHeaders = "errors, content-type")
 69	@RequestMapping("/api")
 70	public class OwnerRestControllerV1 implements OwnersApi {
 71	
 72	    /** Maximum number of owners a single city may contain; creating another owner there is rejected. */
 73	    static final int CITY_CAPACITY = 50;
 74	
 75	    /** Maximum number of owners that may be created per (business-day adjusted) registration date; further creates are rejected. */
 76	    static final int DAILY_OWNER_LIMIT = 100;
 77	
 78	    /** Owners already created on the same registration date beyond which a new owner gets 'bulkSignupWarning'. */
 79	    static final int BULK_SIGNUP_THRESHOLD = 80;
 80	
 81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
 82	
 83	    private final ClinicService clinicService;
 84	
 85	    private final OwnerMapper ownerMapper;
 86	
 87	    private final PetMapper petMapper;
 88	
 89	    private final VisitMapper visitMapper;
 90	
 91	    public OwnerRestControllerV1(ClinicService clinicService,
 92	                                 OwnerMapper ownerMapper,
 93	                                 PetMapper petMapper,
 94	                                 VisitMapper visitMapper) {
 95	        this.clinicService = clinicService;
 96	        this.ownerMapper = ownerMapper;
 97	        this.petMapper = petMapper;
 98	        this.visitMapper = visitMapper;
 99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Transactional
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
130	        // A repeated create with an already-seen key returns the originally created owner.
131	        if (idempotencyKey != null) {
132	            Owner existing = this.clinicService.findOwnerByIdempotencyKey(idempotencyKey);
133	            if (existing != null) {
134	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), ownerLocation(existing), HttpStatus.OK);
135	            }
136	        }
137	        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
138	        if (!missingFields.isEmpty()) {
139	            throw new MissingRequiredFieldsException(missingFields);
140	        }
141	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
142	        OwnerEmail.validate(ownerFieldsDto.getEmail());
143	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
146	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
147	        applyAddress(owner, ownerFieldsDto);
148	        // The householdId is derived from (lastName, postcode) and is part of the identity key. An
149	        // existing household blocks the create unless the new owner declares it shares the household.
150	        owner.setHouseholdId(this.clinicService.householdIdOf(owner));
151	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        if (!declaredHouseholdMember && this.clinicService.householdExists(owner)) {
153	            throw new DuplicateHouseholdException(owner.getHouseholdId());
154	        }
155	        if (this.clinicService.ownerIdentityKeyExists(owner)) {
156	            throw new DuplicateIdentityException(owner.getIdentityKey());
157	        }
158	        if (this.clinicService.countOwnersInCity(ownerFieldsDto.getCity()) >= CITY_CAPACITY) {
159	            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
160	        }
161	        LocalDate registrationDate = BusinessDays.rollForward(
162	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
163	        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
164	        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
165	            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
166	        }
167	        owner.setRegistrationDate(registrationDate);
168	        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
169	        // A declared household member is not a suspected duplicate.
170	        owner.setPossibleDuplicateOf(declaredHouseholdMember ? null : this.clinicService.findPossibleDuplicateOf(owner));
171	        owner.setIdempotencyKey(idempotencyKey);
172	        this.clinicService.saveOwner(owner);
173	        AUDIT.info("Owner created: id={}, customerCode={}, region={}, membershipNumber={}, checkDigit={}, "
174	                + "registrationDate={}, membershipPoints={}, membershipLevel={}",
175	            owner.getId(), owner.getCustomerCode(), ownerMapper.toLocality(owner),
176	            ownerMapper.toMembershipNumber(owner), ownerMapper.toCheckDigit(owner),
177	            owner.getRegistrationDate(), ownerMapper.toMembershipPoints(owner), ownerMapper.toMembershipLevel(owner));
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), ownerLocation(owner), HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
189	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
190	        OwnerEmail.validate(ownerFieldsDto.getEmail());
191	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
192	        applyAddress(currentOwner, ownerFieldsDto);
193	        currentOwner.setCity(ownerFieldsDto.getCity());
194	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
195	        currentOwner.setLastName(ownerFieldsDto.getLastName());
196	        currentOwner.setTelephone(telephone);
197	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
198	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
199	        if (ownerFieldsDto.getRegistrationDate() != null) {
200	            currentOwner.setRegistrationDate(BusinessDays.rollForward(ownerFieldsDto.getRegistrationDate()));
201	        }
202	        if (ownerFieldsDto.getBirthDate() != null) {
203	            currentOwner.setBirthDate(ownerFieldsDto.getBirthDate());
204	        }
205	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
206	        this.clinicService.saveOwner(currentOwner);
207	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Transactional
212	    @Override
213	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        this.clinicService.deleteOwner(owner);
219	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner == null) {
227	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	        }
229	        HttpHeaders headers = new HttpHeaders();
230	        Pet pet = petMapper.toPet(petFieldsDto);
231	        owner.setId(ownerId);
232	        pet.setOwner(owner);
233	        pet.getType().setName(null);
234	        this.clinicService.savePet(pet);
235	        PetDto petDto = petMapper.toPetDto(pet);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
237	            .buildAndExpand(pet.getId()).toUri());
238	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner != null) {
246	            Pet currentPet = this.clinicService.findPetById(petId);
247	            if (currentPet != null) {
248	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
249	                currentPet.setName(petFieldsDto.getName());
250	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
251	                this.clinicService.savePet(currentPet);
252	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
261	        HttpHeaders headers = new HttpHeaders();
262	        Visit visit = visitMapper.toVisit(visitFieldsDto);
263	        Pet pet = new Pet();
264	        pet.setId(petId);
265	        visit.setPet(pet);
266	        this.clinicService.saveVisit(visit);
267	        VisitDto visitDto = visitMapper.toVisitDto(visit);
268	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
269	            .buildAndExpand(visit.getId()).toUri());
270	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
271	    }
272	
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner != null) {
279	            Pet pet = owner.getPet(petId);
280	            if (pet != null) {
281	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
282	            }
283	        }
284	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	    }
286	
287	    /**
288	     * Stores the normalized structured address lines (absent when not supplied) and the composed
289	     * 'address': the structured lines when 'addressLine1' is present, otherwise the flat address.
290	     */
291	    private static void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
292	        owner.setAddressLine1(AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine1()));
293	        owner.setAddressLine2(owner.getAddressLine1() == null ? null
294	            : AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine2()));
295	        owner.setAddress(AddressNormalizer.compose(
296	            ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
297	    }
298	
299	    private static HttpHeaders ownerLocation(Owner owner) {
300	        HttpHeaders headers = new HttpHeaders();
301	        headers.setLocation(UriComponentsBuilder.newInstance()
302	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
303	        return headers;
304	    }
305	
306	    private static String normalizeEmail(String email) {
307	        return email == null ? null : email.toLowerCase(Locale.ROOT);
308	    }
309	}

