import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.util.AddressNormalizer;

/**
 * Determines which of the fields required to create an owner are missing or blank. The address may be
 * supplied either as a structured 'addressLine1' or as the flat 'address'; it is checked in its
 * normalized form, so an address that is blank after normalization counts as missing.
 */
public final class RequiredOwnerFields {

    private RequiredOwnerFields() {
    }

    /**
     * @param owner the owner fields from the request body
     * @return names of required fields that are missing or blank, in declaration order; empty if none
     */
    public static List<String> missingFields(OwnerFieldsDto owner) {
        Map<String, String> required = new LinkedHashMap<>();
        required.put("firstName", owner.getFirstName());
        required.put("lastName", owner.getLastName());
        required.put("address", AddressNormalizer.compose(
            owner.getAddressLine1(), owner.getAddressLine2(), owner.getAddress()));
        required.put("city", owner.getCity());
        required.put("telephone", owner.getTelephone());
        List<String> missing = new ArrayList<>();
        required.forEach((field, value) -> {
            if (value == null || value.isBlank()) {
                missing.add(field);
            }
        });
        return missing;
    }
}
package org.springframework.samples.petclinic.rest.validation;

import java.util.Map;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.mapper.OwnerMapper;

/**
 * Validates optional owner postcodes against the postcode range of the owner's city region.
 */
public final class OwnerPostcode {

    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** Inclusive postcode range per region, keyed by the regions of {@link OwnerMapper#CITY_REGIONS}. */
    public static final Map<String, int[]> RANGES_BY_REGION = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /** The region of owners whose postcode and city match no known region. */
    public static final String UNKNOWN_REGION = "UNKNOWN";

    private OwnerPostcode() {
    }

    /**
     * The owner's region: the region whose range contains the postcode; when the postcode is absent or
     * in no known range, the region of the city from {@link OwnerMapper#CITY_REGIONS}, or
     * {@value #UNKNOWN_REGION} when the city is not listed.
     *
     * @param postcode the postcode, may be {@code null}
     * @param city the city, may be {@code null}
     * @return the region, never {@code null}
     */
    public static String regionOf(String postcode, String city) {
        String postcodeRegion = regionOf(postcode);
        if (postcodeRegion != null) {
            return postcodeRegion;
        }
        return city == null ? UNKNOWN_REGION : OwnerMapper.CITY_REGIONS.getOrDefault(city, UNKNOWN_REGION);
    }

    /**
     * The region whose range in {@link #RANGES_BY_REGION} contains the postcode.
     *
     * @param postcode the postcode, may be {@code null}
     * @return the region, or {@code null} when the postcode is absent, not 4 digits or in no known range
     */
    public static String regionOf(String postcode) {
        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : RANGES_BY_REGION.entrySet()) {
            if (value >= entry.getValue()[0] && value <= entry.getValue()[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * Checks a postcode for the given city. An absent postcode is accepted; a present one must be
     * 4 digits and, when the city has a known region, lie within that region's range.
     *
     * @param postcode the postcode as supplied in the request, may be {@code null}
     * @param city the owner's city
     * @throws InvalidPostcodeException if the postcode is malformed or out of range for the city's region
     */
    public static void validate(String postcode, String city) {
        if (postcode == null) {
            return;
        }
        if (!FOUR_DIGITS.matcher(postcode).matches()) {
            throw new InvalidPostcodeException(postcode, "Postcode must be 4 digits");
        }
        String region = city == null ? null : OwnerMapper.CITY_REGIONS.get(city);
        int[] range = region == null ? null : RANGES_BY_REGION.get(region);
        if (range == null) {
            return;
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode, "Postcode for " + city + " (" + region
                + ") must be between " + range[0] + " and " + range[1]);
        }
    }
}
package org.springframework.samples.petclinic.rest.validation;

import java.util.Locale;
import java.util.Set;

/**
 * Validates optional owner email addresses against a blocklist of disposable email domains.
 */
public final class OwnerEmail {

    /** Disposable email domains; addresses at these domains or any of their subdomains are rejected. */
    public static final Set<String> DISPOSABLE_DOMAINS = Set.of(
        "mailinator.com",
        "tempmail.com",
        "guerrillamail.com");

    private OwnerEmail() {
    }

    /**
     * Checks an email address. An absent address is accepted; a present one must not belong to a
     * domain in {@link #DISPOSABLE_DOMAINS} (or a subdomain of one), compared case-insensitively.
     *
     * @param email the email address as supplied in the request, may be {@code null}
     * @throws InvalidEmailException if the address is at a disposable domain
     */
    public static void validate(String email) {
        if (email == null) {
            return;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return;
        }
        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
        if (domain.endsWith(".")) {
            domain = domain.substring(0, domain.length() - 1);
        }
        for (String blocked : DISPOSABLE_DOMAINS) {
            if (domain.equals(blocked) || domain.endsWith("." + blocked)) {
                throw new InvalidEmailException(email, "Email domain '" + domain + "' is a disposable email domain");
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.validation;

import java.time.LocalDate;

/**
 * Validates optional owner registration dates supplied by clients.
 */
public final class OwnerRegistrationDate {

    private OwnerRegistrationDate() {
    }

    /**
     * Checks a supplied registration date. An absent date is accepted; a present one must not be later
     * than the server's current date. The check applies to the date as supplied, before any weekend
     * roll-forward.
     *
     * @param registrationDate the registration date as supplied in the request, may be {@code null}
     * @throws InvalidRegistrationDateException if the date is later than the server's current date
     */
    public static void validate(LocalDate registrationDate) {
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new InvalidRegistrationDateException(registrationDate.toString(),
                "Registration date must not be later than the current date");
        }
    }
}
