279	/**
280	 * Normalizes owner addresses into a canonical form, used both for storage and for comparing addresses.
281	 */
282	public final class AddressNormalizer {
283	
284	    private static final Map<String, String> ABBREVIATIONS = Map.of(
285	        "ST", "STREET",
286	        "RD", "ROAD",
287	        "AVE", "AVENUE");
288	
289	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
290	
291	    private AddressNormalizer() {
292	    }
293	
294	    /**
295	     * Trims the address, collapses runs of whitespace into a single space, upper-cases it and expands
296	     * the whole-word abbreviations ST, RD and AVE (optionally followed by a '.') to STREET, ROAD and AVENUE.
297	     *
298	     * @param address the address as supplied
299	     * @return the normalized address, empty if the address is {@code null} or blank
300	     */
301	    public static String normalize(String address) {
302	        if (address == null || address.isBlank()) {
303	            return "";
304	        }
305	        return WHITESPACE.splitAsStream(address.strip().toUpperCase(Locale.ROOT))
306	            .map(AddressNormalizer::expand)
307	            .collect(Collectors.joining(" "));
308	    }
309	
310	    /**
311	     * Normalizes an optional address field.
312	     *
313	     * @param address the address field as supplied
314	     * @return the {@link #normalize(String) normalized} field, or {@code null} if it is {@code null} or blank
315	     */
316	    public static String normalizeOptional(String address) {
317	        String normalized = normalize(address);
318	        return normalized.isEmpty() ? null : normalized;
319	    }
320	
321	    /**
322	     * The owner's effective address. When the structured {@code addressLine1} is present it is preferred: the
323	     * normalized line 1, followed by a single space and the normalized line 2 when that is present. Otherwise
324	     * the normalized flat address.
325	     *
326	     * @param addressLine1 the structured first address line, may be {@code null}
327	     * @param addressLine2 the structured second address line, may be {@code null}
328	     * @param address the flat address, may be {@code null}
329	     * @return the normalized effective address, empty if no address is supplied
330	     */
331	    public static String compose(String addressLine1, String addressLine2, String address) {
332	        String line1 = normalizeOptional(addressLine1);
333	        if (line1 == null) {
334	            return normalize(address);
335	        }
336	        String line2 = normalizeOptional(addressLine2);
337	        return line2 == null ? line1 : line1 + " " + line2;
338	    }
339	
340	    private static String expand(String word) {
341	        String bare = word.endsWith(".") ? word.substring(0, word.length() - 1) : word;
342	        return ABBREVIATIONS.getOrDefault(bare, word);
343	    }
