347	import java.time.DayOfWeek;
348	import java.time.LocalDate;
349	import java.util.Set;
350	
351	/**
352	 * Business-day calculations for dates such as an owner's registration date.
353	 */
354	public final class BusinessDays {
355	
356	    /** Fixed public holidays that are never business days. */
357	    static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
358	        LocalDate.of(2026, 1, 1),
359	        LocalDate.of(2026, 1, 26),
360	        LocalDate.of(2026, 4, 25),
361	        LocalDate.of(2026, 12, 25),
362	        LocalDate.of(2026, 12, 28));
363	
364	    private BusinessDays() {
365	    }
366	
367	    /**
368	     * Rolls a date forward past Saturdays, Sundays and public holidays to the next business day;
369	     * a date that is already a business day is returned unchanged.
370	     *
371	     * @param date the date to adjust
372	     * @return the business day on or after {@code date}, or {@code null} if {@code date} is {@code null}
373	     */
374	    public static LocalDate rollForward(LocalDate date) {
375	        if (date == null) {
376	            return null;
377	        }
378	        LocalDate result = date;
379	        while (!isBusinessDay(result)) {
380	            result = result.plusDays(1);
381	        }
382	        return result;
383	    }
384	
385	    /**
386	     * @param date the date to check
387	     * @return {@code true} if {@code date} is neither a weekend day nor a public holiday
388	     */
389	    public static boolean isBusinessDay(LocalDate date) {
390	        DayOfWeek dayOfWeek = date.getDayOfWeek();
391	        return dayOfWeek != DayOfWeek.SATURDAY && dayOfWeek != DayOfWeek.SUNDAY
392	            && !PUBLIC_HOLIDAYS.contains(date);
393	    }
394	}

