package org.springframework.samples.petclinic.repository.springdatajpa;




@Profile("spring-data-jpa")
public interface SpringDataOwnerRepository extends OwnerRepository, Repository<Owner, Integer> {

    @Override
    @Query("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName%")
    Collection<Owner> findByLastName(@Param("lastName") String lastName);

    @Override
    @Query(
        value = "SELECT owner FROM Owner owner WHERE owner.lastName LIKE CONCAT(:lastName, '%')",
        countQuery = "SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE CONCAT(:lastName, '%')")
    Page<Owner> findByLastName(@Param("lastName") String lastName, Pageable pageable);

    @Override
    @Query(
        value = "SELECT owner FROM Owner owner",
        countQuery = "SELECT COUNT(owner) FROM Owner owner")
    Page<Owner> findAll(Pageable pageable);

    @Override
    @Query("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id")
    Owner findById(@Param("id") int id);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE owner.telephone = :telephone")
    List<Owner> findByTelephone(@Param("telephone") String telephone);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE owner.idempotencyKey = :idempotencyKey")
    Owner findByIdempotencyKey(@Param("idempotencyKey") String idempotencyKey);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = :lastName")
    List<Owner> findByLastNameIgnoringCase(@Param("lastName") String lastName);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.firstName) = :firstName AND LOWER(owner.lastName) = :lastName")
    long countByFirstNameAndLastNameIgnoringCase(@Param("firstName") String firstName, @Param("lastName") String lastName);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.city) = :city")
    long countByCityIgnoringCase(@Param("city") String city);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate")
    long countByRegistrationDate(@Param("registrationDate") LocalDate registrationDate);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE owner.householdId = :householdId")
    long countByHouseholdId(@Param("householdId") String householdId);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE owner.householdId = :householdId AND owner.deleted = false")
    long countNotDeletedByHouseholdId(@Param("householdId") String householdId);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE owner.customerCode = :customerCode")
    long countByCustomerCode(@Param("customerCode") String customerCode);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner")
    long count();
}
package org.springframework.samples.petclinic.repository;



public interface OwnerRepository {

    /**
     * Retrieve <code>Owner</code>s from the data store by last name, returning all owners whose last name <i>starts</i>
     * with the given name.
     *
     * @param lastName Value to search for
     * @return a <code>Collection</code> of matching <code>Owner</code>s (or an empty <code>Collection</code> if none
     * found)
     */
    Collection<Owner> findByLastName(String lastName) throws DataAccessException;

    Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException;

    /**
     * Retrieve an <code>Owner</code> from the data store by id.
     *
     * @param id the id to search for
     * @return the <code>Owner</code> if found
     * @throws org.springframework.dao.DataRetrievalFailureException if not found
     */
    Owner findById(int id) throws DataAccessException;

    /**
     * Retrieve all <code>Owner</code>s that have the given telephone number.
     *
     * @param telephone the (normalized) telephone number to search for
     * @return the matching owners
     */
    List<Owner> findByTelephone(String telephone) throws DataAccessException;

    /**
     * Retrieve the <code>Owner</code> that was created with the given idempotency key.
     *
     * @param idempotencyKey the idempotency key to search for
     * @return the matching owner, or <code>null</code> if none
     */
    Owner findByIdempotencyKey(String idempotencyKey) throws DataAccessException;

    /**
     * Retrieve all <code>Owner</code>s whose last name, compared case-insensitively, equals the given name.
     *
     * @param lastName the lower-cased last name to search for
     * @return the matching owners
     */
    List<Owner> findByLastNameIgnoringCase(String lastName) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s whose first and last names, compared case-insensitively, equal the given names.
     *
     * @param firstName the lower-cased first name to search for
     * @param lastName the lower-cased last name to search for
     * @return the number of matching owners
     */
    long countByFirstNameAndLastNameIgnoringCase(String firstName, String lastName) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s whose city, compared case-insensitively, equals the given city.
     *
     * @param city the lower-cased city to search for
     * @return the number of matching owners
     */
    long countByCityIgnoringCase(String city) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s whose registration date equals the given date.
     *
     * @param registrationDate the registration date to search for
     * @return the number of matching owners
     */
    long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s that belong to the household with the given ID.
     *
     * @param householdId the household ID to search for
     * @return the number of matching owners
     */
    long countByHouseholdId(String householdId) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s that belong to the household with the given ID and are not soft-deleted.
     *
     * @param householdId the household ID to search for
     * @return the number of matching non-deleted owners
     */
    long countNotDeletedByHouseholdId(String householdId) throws DataAccessException;

    /**
     * Count the <code>Owner</code>s that have the given customer code.
     *
     * @param customerCode the customer code to search for
     * @return the number of matching owners
     */
    long countByCustomerCode(String customerCode) throws DataAccessException;

    /**
     * Count all <code>Owner</code>s in the data store.
     *
     * @return the number of owners
     */
    long count() throws DataAccessException;


    /**
     * Save an <code>Owner</code> to the data store, either inserting or updating it.
     *
     * @param owner the <code>Owner</code> to save
     * @see BaseEntity#isNew
     */
    void save(Owner owner) throws DataAccessException;

    /**
     * Retrieve <code>Owner</code>s from the data store, returning all owners 
     *
     * @return a <code>Collection</code> of <code>Owner</code>s (or an empty <code>Collection</code> if none
     * found)
     */
	Collection<Owner> findAll() throws DataAccessException;

    Page<Owner> findAll(Pageable pageable) throws DataAccessException;

    /**
     * Delete an <code>Owner</code> to the data store by <code>Owner</code>.
     *
     * @param owner the <code>Owner</code> to delete
     * 
     */
	void delete(Owner owner) throws DataAccessException;


}
